/* Generated by scripts/build.mjs. Static app only; plans remain in local storage. */
const PRECACHE = __PRECACHE__;
const RELEASE = '__RELEASE__';
const SCOPE = self.registration.scope;
const PREFIX = 'droneinvest:' + new URL(SCOPE).pathname + ':';
const CACHE = PREFIX + RELEASE;
const HOME = new URL('./', SCOPE).href;
const URLS = PRECACHE.map(path => new URL(path, SCOPE).href);
self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(URLS.map(url => new Request(url, {cache: 'reload'})))));
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(key => key.startsWith(PREFIX) && key !== CACHE).map(key => caches.delete(key)));
    await self.clients.claim();
  })());
});
self.addEventListener('message', event => {
  if (event.data?.type === 'ACTIVATE_UPDATE') self.skipWaiting();
});
self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== new URL(SCOPE).origin || !url.href.startsWith(SCOPE)) return;
  // Serve a consistent release, including its HTML, until the user accepts an update.
  if (request.mode === 'navigate') {
    const homePath = new URL(HOME).pathname;
    if (url.pathname !== homePath && url.pathname !== homePath + 'index.html') {
      event.respondWith(Promise.resolve(Response.redirect(HOME, 302)));
      return;
    }
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      return await cache.match(HOME) || fetch(request);
    })());
    return;
  }
  url.search = ''; url.hash = '';
  if (!URLS.includes(url.href)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    return await cache.match(url.href) || fetch(request);
  })());
});
